\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\pagestyle{empty}

%% ── Samsung Color Theme ──
% Deep navy/blue Samsung-inspired palette
\definecolor{primary}{HTML}{0A1E3C}      % deep navy
\definecolor{secondary}{HTML}{1428A0}    % Samsung signature blue
\definecolor{accent}{HTML}{1B6EF3}       % bright blue accent
\definecolor{gold}{HTML}{B8860B}         % premium gold for flagship highlights
\definecolor{goldlight}{HTML}{FFD700}    % bright gold
\definecolor{bgposter}{HTML}{06101F}     % very dark navy background
\definecolor{bgcard}{HTML}{0D1F3C}       % card background (slightly lighter)
\definecolor{bgcardhero}{HTML}{0F1E38}   % hero card bg
\definecolor{bghighlight}{HTML}{162847}  % subtle highlight
\definecolor{bggold}{HTML}{1A1608}       % gold-tinted dark bg
\definecolor{textwhite}{HTML}{F0F4FF}    % near-white text
\definecolor{textmuted}{HTML}{8BAAC8}    % muted blue-grey
\definecolor{textgold}{HTML}{D4A017}     % gold text
\definecolor{stathighlight}{HTML}{0A1E6E}
\definecolor{newbadge}{HTML}{1428A0}

\pagecolor{bgposter}
\color{textwhite}

%% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\bullet$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}\bfseries\arabic*.}}

%% ── Card styles ──
\tcbset{
  % Dark navy card (standard)
  navycard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=secondary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.5, color=black},
  },
  % Accent blue card
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bghighlight,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=accent,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.5, color=black},
  },
  % Gold/premium card (flagships)
  goldcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bggold,
    borderline west={6pt}{0pt}{goldlight},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{goldlight},
    coltitle=goldlight, colbacktitle=gold,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.6, color=black},
  },
  % Highlight/CTA card
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colframe=accent!60, colback=stathighlight,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.5, color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=1mm},
]

%% ══════════════════════════════════════════════════════════
%%  TITLE BAR  (rows top → row4)
%% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=primary,
  colframe=primary,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  underlay={
    \fill[secondary!30, opacity=0.3]
      ([xshift=0pt,yshift=0pt]frame.south west)
      rectangle ([xshift=600pt,yshift=0pt]frame.south east);
    \fill[accent, opacity=0.08] (frame.north west) rectangle (frame.south east);
  },
  drop shadow={opacity=0.6, color=black},
]{name=titlebar, column=1, span=3, between=top and row4}{%
  {\fontsize{28}{34}\selectfont\bfseries\color{textmuted}\MakeUppercase{Samsung}}%
  \\[4pt]%
  {\fontsize{72}{84}\selectfont\bfseries\color{textwhite}Galaxy Ecosystem}%
  \\[6pt]%
  {\fontsize{52}{62}\selectfont\bfseries\color{goldlight}2025}%
  \\[8pt]%
  {\fontsize{26}{32}\selectfont\color{textmuted}
    Innovation Across Every Category\ \ |\ \ AI-Powered. Seamlessly Connected.}%
}

%% ══════════════════════════════════════════════════════════
%%  STATS BANNER  (rows row4 → row6)
%% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=secondary,
  colframe=secondary,
  arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
]{name=statbanner, column=1, span=3, between=row4 and row6}{%
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{primary}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{goldlight} 7+}\\[3pt]%
      {\fontsize{24}{30}\selectfont\color{textwhite} Product Categories}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{primary}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{goldlight} 14}\\[3pt]%
      {\fontsize{24}{30}\selectfont\color{textwhite} Featured Products}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{primary}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{goldlight} 2}\\[3pt]%
      {\fontsize{24}{30}\selectfont\color{textwhite} Flagship Launches}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{primary}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{goldlight} 4+}\\[3pt]%
      {\fontsize{24}{30}\selectfont\color{textwhite} AI-Branded Products}\vspace{8pt}%
    }}%
  \end{minipage}%
}

%% ══════════════════════════════════════════════════════════
%%  ROW A — Hero flagships + Ecosystem intro
%%  col1: Galaxy S26 Ultra hero    (row6 → row12)
%%  col2: Galaxy Buds4 Pro hero    (row6 → row12)
%%  col3: Ecosystem overview       (row6 → row12)
%% ══════════════════════════════════════════════════════════

%% ── Galaxy S26 Ultra ──
\posterbox[
  goldcard,
  title={%
    \raisebox{2pt}{\colorbox{goldlight}{\fontsize{18}{22}\selectfont\bfseries\color{primary}\ \ NEW\ \ }}\quad
    Galaxy S26 Ultra
  },
]{name=s26ultra, column=1, between=row6 and row12}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  %
  \vspace{4pt}
  {\fontsize{34}{42}\selectfont\bfseries\color{goldlight}Samsung's Most Advanced Smartphone}\\[8pt]
  %
  \begin{itemize}[itemsep=10pt, label={\color{goldlight}$\star$}]
    \item Pro-grade camera system + S Pen integrated
    \item On-device \textbf{Galaxy AI} for photo, productivity \& translation
    \item Premium materials — titanium frame, Corning Glass
    \item Flagship Ultra series — top of the Galaxy lineup
  \end{itemize}
  \vspace{10pt}
  \colorbox{bghighlight}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{30}{38}\selectfont\color{accent}$\Rightarrow$\ \textbf{Galaxy AI on board} — intelligent,
    real-time, on-device}
    \vspace{6pt}
  }}
  \vspace{8pt}
  \colorbox{bggold}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{28}{35}\selectfont\color{goldlight}\textbf{Category:} Smartphones\ \ |\ \ \textbf{Status:} \textsc{New 2025}}
    \vspace{6pt}
  }}
}

%% ── Galaxy Buds4 Pro ──
\posterbox[
  goldcard,
  title={%
    \raisebox{2pt}{\colorbox{goldlight}{\fontsize{18}{22}\selectfont\bfseries\color{primary}\ \ NEW\ \ }}\quad
    Galaxy Buds4 Pro
  },
]{name=buds4pro, column=2, between=row6 and row12}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  %
  \vspace{4pt}
  {\fontsize{34}{42}\selectfont\bfseries\color{goldlight}Next-Gen Audio, Zero Compromise}\\[8pt]
  %
  \begin{itemize}[itemsep=10pt, label={\color{goldlight}$\star$}]
    \item Next-generation Active Noise Cancellation
    \item High-fidelity audio — audiophile-grade tuning
    \item Seamless pairing across all Galaxy devices
    \item AI-enhanced adaptive sound profiles
  \end{itemize}
  \vspace{10pt}
  \colorbox{bghighlight}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{30}{38}\selectfont\color{accent}$\Rightarrow$\ \textbf{Bespoke AI audio} — adaptive, personal, precise}
    \vspace{6pt}
  }}
  \vspace{8pt}
  \colorbox{bggold}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{28}{35}\selectfont\color{goldlight}\textbf{Category:} Audio\ \ |\ \ \textbf{Status:} \textsc{New 2025}}
    \vspace{6pt}
  }}
}

%% ── Ecosystem Overview ──
\posterbox[
  navycard,
  title={The Complete Galaxy Ecosystem},
]{name=ecosystem, column=3, between=row6 and row12}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  %
  \vspace{4pt}
  {\fontsize{32}{40}\selectfont\color{accent}From your pocket to every room — one seamless AI ecosystem.}
  \vspace{10pt}

  \begin{itemize}[itemsep=10pt]
    \item \textbf{Smartphones} — Galaxy S26 Ultra \textcolor{goldlight}{(New)}
    \item \textbf{Foldables} — Galaxy Z Fold7, Z Flip7
    \item \textbf{Tablets} — Galaxy Tab S11 Series
    \item \textbf{Wearables} — Galaxy Watch Ultra
    \item \textbf{Audio} — Galaxy Buds4 Pro \textcolor{goldlight}{(New)}
    \item \textbf{TVs} — Neo QLED 8K, The Frame Pro
    \item \textbf{Home} — Bespoke AI appliances
  \end{itemize}
  \vspace{8pt}
  \colorbox{stathighlight}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{28}{35}\selectfont\color{textwhite}\textbf{7+ Categories.\ \ 14 Products.\ \ 1 Ecosystem.}}
    \vspace{6pt}
  }}
}

%% ══════════════════════════════════════════════════════════
%%  ROW B — AI Integration + Foldables/Wearables + Entertainment
%%  col1: AI branding deep-dive    (row12 → row16)
%%  col2: Foldables & Wearables    (row12 → row16)
%%  col3: Entertainment & Monitors (row12 → row16)
%% ══════════════════════════════════════════════════════════

%% ── Galaxy AI & Bespoke AI ──
\posterbox[
  bluecard,
  title={Galaxy AI \& Bespoke AI},
]{name=aicard, column=1, between=row12 and row16}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  \vspace{4pt}
  {\fontsize{32}{40}\selectfont\color{accent}\textbf{AI is the foundation — not a feature.}}
  \vspace{8pt}

  \colorbox{bgcard}{\parbox{0.94\linewidth}{%
    \vspace{5pt}
    {\fontsize{28}{36}\selectfont\color{textmuted}\textbf{Galaxy AI} (Mobile)}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textwhite}S26 Ultra $\cdot$ Z Fold7 $\cdot$ Z Flip7 — on-device intelligence: photo enhancement, real-time translation, productivity tools}
    \vspace{5pt}
  }}
  \vspace{6pt}
  \colorbox{bgcard}{\parbox{0.94\linewidth}{%
    \vspace{5pt}
    {\fontsize{28}{36}\selectfont\color{textmuted}\textbf{Bespoke AI} (Home)}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textwhite}Refrigerators, Laundry — smart energy management, usage learning, personalized automation}
    \vspace{5pt}
  }}
}

%% ── Foldables & Wearables ──
\posterbox[
  navycard,
  title={Foldables \& Wearables},
]{name=foldwear, column=2, between=row12 and row16}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  \vspace{4pt}

  {\fontsize{32}{40}\selectfont\bfseries\color{accent}Galaxy Z Series}\\[6pt]
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Z Fold7} — book-style foldable, desktop-class multitasking
    \item \textbf{Z Flip7} — compact flip, Galaxy AI photography
  \end{itemize}
  \vspace{8pt}
  {\fontsize{32}{40}\selectfont\bfseries\color{accent}Galaxy Watch Ultra}\\[6pt]
  \begin{itemize}[itemsep=6pt]
    \item Rugged premium smartwatch
    \item Advanced health + fitness tracking
    \item Integrates with Galaxy AI ecosystem
  \end{itemize}
}

%% ── Entertainment & Monitors ──
\posterbox[
  bluecard,
  title={Entertainment \& Monitors},
]{name=entertain, column=3, between=row12 and row16}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  \vspace{4pt}

  {\fontsize{32}{40}\selectfont\bfseries\color{accent}Televisions}\\[6pt]
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Neo QLED 8K TV} — 8K AI upscaling, quantum precision
    \item \textbf{The Frame Pro} — art-mode QLED, lifestyle design
    \item \textbf{Q-Series Soundbar} — immersive room-filling audio
  \end{itemize}
  \vspace{8pt}
  {\fontsize{32}{40}\selectfont\bfseries\color{accent}Gaming Monitor}\\[6pt]
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Odyssey OLED G9} — curved OLED, ultra-fast response
  \end{itemize}
}

%% ══════════════════════════════════════════════════════════
%%  ROW C — Category Highlights Table + Smart Home + Tagline
%%  col1-2: Category table (span=2)   (row16 → bottom)
%%  col3:   Tagline / CTA             (row16 → bottom)
%% ══════════════════════════════════════════════════════════

%% ── Category Highlights Table ──
\posterbox[
  navycard,
  title={Category Highlights at a Glance},
]{name=cattable, column=1, span=2, between=row16 and bottom}{%
  \fontsize{28}{36}\selectfont\color{textwhite}
  \vspace{4pt}
  \renewcommand{\arraystretch}{1.55}
  \setlength{\tabcolsep}{10pt}
  \begin{tabular}{>{\bfseries\color{accent}}l >{\color{textwhite}}l >{\color{textmuted}}l}
    \rowcolor{secondary!70}
    \multicolumn{1}{l}{\fontsize{26}{32}\selectfont\bfseries\color{textwhite}Category}
    & \fontsize{26}{32}\selectfont\bfseries\color{textwhite}Product
    & \fontsize{26}{32}\selectfont\bfseries\color{textwhite}Status \\
    \rowcolor{bgcard}
    Smartphones & Galaxy S26 Ultra & \textcolor{goldlight}{\bfseries NEW 2025} \\
    \rowcolor{bghighlight}
    Foldables   & Galaxy Z Fold7 $\cdot$ Z Flip7 & Current \\
    \rowcolor{bgcard}
    Tablets     & Galaxy Tab S11 Series & Current \\
    \rowcolor{bghighlight}
    Wearables   & Galaxy Watch Ultra & Current \\
    \rowcolor{bgcard}
    Audio       & Galaxy Buds4 Pro & \textcolor{goldlight}{\bfseries NEW 2025} \\
    \rowcolor{bghighlight}
    Television  & Neo QLED 8K $\cdot$ The Frame Pro & Current \\
    \rowcolor{bgcard}
    Audio/Home  & Q-Series Soundbar & Current \\
    \rowcolor{bghighlight}
    Monitors    & Odyssey OLED G9 Gaming & Current \\
    \rowcolor{bgcard}
    Kitchen     & Bespoke AI Refrigerator & Current \\
    \rowcolor{bghighlight}
    Laundry     & Bespoke AI Laundry & Current \\
    \rowcolor{bgcard}
    Cleaning    & Jet Stick Vacuums & Current \\
    \rowcolor{bghighlight}
    Climate     & Air Conditioners & Current \\
  \end{tabular}
}

%% ── CTA / Tagline card ──
\posterbox[
  highlightcard,
  title={Why Galaxy?},
]{name=cta, column=3, between=row16 and bottom}{%
  \fontsize{30}{38}\selectfont\color{textwhite}
  \vspace{4pt}

  {\fontsize{36}{44}\selectfont\bfseries\color{goldlight}
    Every device, better together.}
  \vspace{10pt}

  \begin{itemize}[itemsep=10pt, label={\color{accent}$\Rightarrow$}]
    \item AI woven into \textbf{every} product category
    \item Seamless connection from pocket $\to$ living room $\to$ kitchen
    \item \textbf{7+ categories} — one unified Galaxy experience
    \item Premium flagship quality across the lineup
  \end{itemize}
  \vspace{10pt}
  \colorbox{primary}{\parbox{0.94\linewidth}{%
    \vspace{8pt}
    \centering
    {\fontsize{32}{40}\selectfont\bfseries\color{textwhite}Discover the 2025}\\[4pt]
    {\fontsize{40}{48}\selectfont\bfseries\color{goldlight}Galaxy Ecosystem}\\[4pt]
    {\fontsize{26}{32}\selectfont\color{textmuted}samsung.com/galaxy}
    \vspace{8pt}
  }}
  \vspace{8pt}
  \colorbox{bgcard}{\parbox{0.94\linewidth}{%
    \vspace{6pt}
    \centering
    {\fontsize{26}{32}\selectfont\color{textmuted}
      \textbf{Smart Home:} Jet Stick Vacuums $\cdot$ Air Conditioners\\[3pt]
      Bespoke AI — intelligent living, every room
    }
    \vspace{6pt}
  }}
}

\end{tcbposter}
\end{document}

